package com.numbers;
//wap to print the factors of  given numbers
public class Numbers8 {
	public static void print_fact(int num) {
		for (int i=1;i<=num;i++) {
			System.out.println(i);
			
		}
	}

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num=12;
		print_fact(num);

	}

}
